         const size = view.getUint32(offset + 4, true);
         if (tag(offset) === 'data' && size === 0xffffffff) {
             view.setUint32(offset + 4, bytes.length - offset - 8, true);
             break;
         }
         offset += 8 + size + (size % 2);
     }
     return bytes;
